/* ============================================================
   MERCHANDISING: categories, landed cost & pricing rules,
   photos, kits, packages, catalog, collection suggestions,
   delivery price matrix
   ============================================================ */
const DEFAULT_CATEGORIES=[["Bedroom",["Beds","Headboards","Dressers","Chests","Nightstands","Mirrors","Armoires","Vanities","Bedroom sets"]],["Living Room",["Sofas","Loveseats","Sectionals","Sleepers","Recliners","Accent chairs","Ottomans","Coffee tables","End tables","Console tables","TV stands","Entertainment centers"]],["Dining Room",["Dining tables","Dining chairs","Benches","Bar stools","Counter stools","Servers & buffets","China cabinets","Dining sets"]],["Office",["Desks","Office chairs","Bookcases","File cabinets","Credenzas"]],["Youth",["Twin beds","Full beds","Bunk beds","Loft beds","Youth dressers","Youth nightstands","Youth desks"]],["Mattress",["Mattresses","Foundations","Adjustable bases","Protectors","Pillows","Bedding"]],["Accessories",["Rugs","Lamps","Wall art","Mirrors","Throw pillows","Throws","Clocks","Plants & decor"]],["Outdoor",["Outdoor seating","Outdoor dining","Fire pits","Umbrellas"]],["Appliances",["Refrigerators","Ranges","Washers","Dryers","Dishwashers"]],["Electronics",["TVs","Audio","Accessories"]],["Services",["Services"]]];
const DEFAULT_COST_RULES={freightPct:8,addPct:0,surchargeFlat:0,surchargePct:0,multiplier:2,rounding:"up",cents:"none"};
const DEFAULT_MATRIX={orderBands:[500,2000],distBands:[10,25],fees:[[79,119,169],[69,99,149],[0,49,99]]};
const DEFAULT_DELIVERY_OPTIONS=[{id:"wg",name:"White-glove delivery & setup",add:0,setup:true,default:true},{id:"drop",name:"Drop-off — doorstep / garage only",add:-25,setup:false},{id:"carrier",name:"Carrier — UPS / FedEx / freight",add:0,setup:false,carrier:true}];
function categories(){ const st=storeSettings(); return (st.categories&&st.categories.length?st.categories:DEFAULT_CATEGORIES.map(([name,subs])=>({name,subs:subs.slice()}))); }
function categoryNames(){ return categories().map(c=>c.name); }
function subcats(cat){ return (categories().find(c=>c.name===cat)||{}).subs||[]; }
const LEGACY_CAT={"Sofas & Sectionals":["Living Room","Sofas"],"Recliners & Chairs":["Living Room","Recliners"],"Living room tables":["Living Room","Coffee tables"],"Dining":["Dining Room","Dining tables"],"Bedroom furniture":["Bedroom","Beds"],"Mattresses":["Mattress","Mattresses"],"Bases & Foundations":["Mattress","Foundations"],"Adjustable bases":["Mattress","Adjustable bases"],"Protectors":["Mattress","Protectors"],"Pillows & Bedding":["Mattress","Pillows"],"Rugs & Decor":["Accessories","Rugs"],"Storage & Office":["Office","Bookcases"],"Outdoor":["Outdoor","Outdoor seating"],"Services":["Services","Services"]};
function normalizeCategory(p){ if(LEGACY_CAT[p.category]&&!p.subcategory){ const [c,s]=LEGACY_CAT[p.category]; p.category=c; p.subcategory=s; return true; } return false; }
const isProtector=x=>x&&(x.subcategory==="Protectors"||x.category==="Protectors");
const isBase=x=>x&&["Foundations","Adjustable bases","Bases & Foundations"].includes(x.subcategory||x.category);
const isPillow=x=>x&&["Pillows","Bedding","Pillows & Bedding"].includes(x.subcategory||x.category);
function costRules(){ return Object.assign({},DEFAULT_COST_RULES,storeSettings().costRules||{}); }
function vendorRules(v){ if(!v) return {}; const r={}; ["freightPct","addPct","surchargeFlat","surchargePct"].forEach(k=>{ if(v[k]!==undefined&&v[k]!==""&&v[k]!==null) r[k]=+v[k]; }); if(v.rounding) r.rounding=v.rounding; if(v.cents) r.cents=v.cents; const m=v.multiplier!==undefined&&v.multiplier!==""&&v.multiplier!==null?+v.multiplier:(v.markup?1+(+v.markup)/100:null); if(m) r.multiplier=m; return r; }
function costRulesFor(p){ const v=p&&p.vendorId?byId("vendors",p.vendorId):null; return Object.assign({},costRules(),vendorRules(v)); }
function ruleSource(p,key){ const v=p&&p.vendorId?byId("vendors",p.vendorId):null; if(p&&p[key==="multiplier"?"multiplier":key]!==undefined&&p[key]!==""&&p[key]!==null) return "item"; if(v&&vendorRules(v)[key]!==undefined) return v.name; return "store"; }
function landedCost(p){ if(!p) return 0; if(p.isKit) return kitLanded(p); const r=costRulesFor(p); const cost=+p.cost||0; const freight=p.freight!==undefined&&p.freight!==""&&p.freight!==null?+p.freight:cost*(r.freightPct/100); const add=cost*((p.addPct!==undefined&&p.addPct!==""&&p.addPct!==null?+p.addPct:r.addPct)/100); const sur=(p.surcharge!==undefined&&p.surcharge!==""&&p.surcharge!==null?+p.surcharge:r.surchargeFlat)+cost*(r.surchargePct/100); return round2(cost+freight+add+sur); }
function applyRounding(raw,r){ r=r||costRules(); const mode=r.rounding||"up"; const f=mode==="up"?Math.ceil:mode==="down"?Math.floor:Math.round; if(r.cents==="keep") return round2(raw); if(r.cents==="none") return f(raw); const c=r.cents===".95"?0.95:0.99; const base=mode==="down"?Math.floor(raw):mode==="up"?Math.ceil(raw):Math.round(raw); const v=base-1+c; return v<raw&&mode==="up"?base+c:v; }
function categoryMultiplier(cat){ const cr=storeSettings().categoryRules||{}; const v=cr[cat]&&cr[cat].multiplier; return v?+v:null; }
function suggestPrice(p){ const r=costRulesFor(p); const vr=p&&p.vendorId?vendorRules(byId("vendors",p.vendorId)):{}; const mult=p&&p.multiplier?+p.multiplier:(vr.multiplier||categoryMultiplier(p&&p.category)||r.multiplier); let price=applyRounding(landedCost(p)*mult,r); if(p&&p.map&&price<+p.map) price=+p.map; return price; }
function kitLanded(p){ return round2((p.kitItems||[]).reduce((a,k)=>{const c=byId("products",k.productId); return a+(c?landedCost(c)*k.qty:0)},0)); }
function kitStock(p){ const ks=p.kitItems||[]; if(!ks.length) return 0; return Math.max(0,Math.min(...ks.map(k=>{const c=byId("products",k.productId); return c?Math.floor((c.stock||0)/k.qty):0}))); }
function kitPieces(p){ return (p.kitItems||[]).reduce((a,k)=>{const c=byId("products",k.productId); return a+k.qty*(c?(c.pieces||1):1)},0); }
const effStock=p=>p.isKit?kitStock(p):(p.stock||0);
function photoThumb(p,size){ size=size||44; if(p.photo) return `<img src="${p.photo}" style="width:${size}px;height:${size}px;object-fit:cover;border-radius:8px;flex:none">`; return `<div style="width:${size}px;height:${size}px;border-radius:8px;background:var(--sage2);color:var(--ink2);display:flex;align-items:center;justify-content:center;font-size:${Math.round(size/3.2)}px;font-weight:800;flex:none">${esc(initials(p.name||"?"))}</div>`; }

/* ---------- item form ---------- */
function editProduct(id){
  const st=storeSettings(); const r=costRules(); const cats=categories();
  const p=byId("products",id)||{sku:"",category:cats[0].name,subcategory:"",collection:"",model:"",color:"",finish:"",size:"",dims:"",cost:0,freight:"",addPct:"",surcharge:"",multiplier:"",price:0,priceManual:false,msrp:0,stock:0,reorderAt:1,vendorId:"",bin:"",pieces:1,warrantyYears:1,comfort:"Medium",matType:"Hybrid",trial:true,floorSample:false,isKit:false,kitItems:[],photo:""};
  const isM=isMattress(p);
  modal(`<h2>${id?"Edit item":"Add item"}</h2>
  <div class="grid g3"><div class="field"><label class="f">SKU / barcode</label><div class="row"><input type="text" id="p_sku" value="${esc(p.sku)}" placeholder="${st.skuPrefix}-1001"><button class="btn s fx" onclick="document.getElementById('p_sku').value='${st.skuPrefix}-'+(1000+S.products.length+1)">Auto</button></div></div><div class="field"><label class="f">Model #</label><input type="text" id="p_model" value="${esc(p.model||"")}" placeholder="e.g. B2587-58"></div><div class="field"><label class="f">Collection</label><input type="text" id="p_coll" value="${esc(p.collection||"")}" list="colls" placeholder="e.g. Alder"><datalist id="colls">${[...new Set(S.products.map(x=>x.collection).filter(Boolean))].map(c=>`<option value="${esc(c)}">`).join("")}</datalist></div></div>
  <div class="field"><label class="f">Name</label><input type="text" id="p_name" value="${esc(p.name||"")}" placeholder="e.g. Alder king panel headboard"></div>
  <div class="grid g3"><div class="field"><label class="f">Category</label><select id="p_cat" onchange="pfCat(this.value)">${optsList(categoryNames(),p.category)}</select></div><div class="field"><label class="f">Sub-category</label><select id="p_sub">${optsList(subcats(p.category),p.subcategory,"—")}</select></div><div class="field"><label class="f">Vendor / supplier</label><select id="p_vendor" onchange="pfVendor()">${opts(S.vendors,p.vendorId,x=>x.name,x=>x.id,"None")}</select></div></div>
  <div class="grid g4"><div class="field"><label class="f">Color</label><input type="text" id="p_color" value="${esc(p.color||"")}" list="dl_colors"><datalist id="dl_colors">${[...new Set(colorNames().concat(S.products.map(x=>x.color).filter(Boolean)))].map(s=>`<option value="${esc(s)}">`).join("")}</datalist></div><div class="field"><label class="f">Cover / finish</label><input type="text" id="p_finish" value="${esc(p.finish||"")}" list="dl_finishes" placeholder="Leather, walnut veneer…"><datalist id="dl_finishes">${[...new Set(finishNames().concat(S.products.map(x=>x.finish).filter(Boolean)))].map(s=>`<option value="${esc(s)}">`).join("")}</datalist></div><div class="field"><label class="f">Size</label><input type="text" id="p_size" value="${esc(p.size||"")}" list="sizes" placeholder="King, 84in…"><datalist id="sizes">${mattressSizes().map(s=>`<option value="${esc(s)}">`).join("")}</datalist></div><div class="field"><label class="f">Dimensions (W × D × H)</label><input type="text" id="p_dims" value="${esc(p.dims||"")}" placeholder='84" × 38" × 36"'></div></div>
  <div id="matfields" style="${isM?"":"display:none"}"><div class="grid g3"><div class="field"><label class="f">Comfort</label><select id="p_comfort">${optsList(comforts(),p.comfort)}</select></div><div class="field"><label class="f">Type</label><select id="p_mtype">${optsList(matTypes(),p.matType)}</select></div><div class="field"><label class="f">Sleep trial</label><select id="p_trial"><option value="1" ${p.trial!==false?"selected":""}>${st.trialNights}-night trial</option><option value="0" ${p.trial===false?"selected":""}>No trial (final sale)</option></select></div></div></div>
  <div class="grid g3"><div class="field"><label class="f">Vendor item #</label><input type="text" id="p_vsku" value="${esc(p.vendorSku||"")}"></div><div class="field"><label class="f">Warehouse bin</label><input type="text" id="p_bin" value="${esc(p.bin||"")}"></div><div class="field"><label class="f">Photo</label><div class="row"><span class="fx" id="p_photo_prev">${p.photo?photoThumb(p,40):""}</span><input type="file" accept="image/*" onchange="uploadProductPhoto(this)"></div></div></div>
  <h3 style="margin:6px 0 8px">Cost & price</h3>
  <div class="muted small" id="p_rulesrc" style="margin:-4px 0 8px"></div><div class="grid g4"><div class="field"><label class="f">Vendor cost</label><input type="number" step="0.01" id="p_cost" value="${p.cost}" oninput="pfCalc()"></div><div class="field"><label class="f">Freight $ <span id="p_fr_lbl" class="muted"></span></label><input type="number" step="0.01" id="p_freight" value="${p.freight??""}" oninput="pfCalc()"></div><div class="field"><label class="f">Extra cost % <span id="p_ad_lbl" class="muted"></span></label><input type="number" step="0.1" id="p_addpct" value="${p.addPct??""}" oninput="pfCalc()"></div><div class="field"><label class="f">Surcharge $ <span id="p_su_lbl" class="muted"></span></label><input type="number" step="0.01" id="p_sur" value="${p.surcharge??""}" oninput="pfCalc()"></div></div>
  <div class="grid g4"><div class="field"><label class="f">Landed cost</label><input type="text" id="p_landed" value="${money(landedCost(p))}" readonly style="background:var(--sage2)"></div><div class="field"><label class="f">Multiplier <span id="p_mu_lbl" class="muted"></span></label><input type="number" step="0.05" id="p_mult" value="${p.multiplier||""}" oninput="pfCalc()"></div><div class="field"><label class="f">Selling price <span class="muted">(${r.rounding}, ${r.cents==="none"?"no cents":r.cents})</span></label><div class="row"><input type="number" step="0.01" id="p_price" value="${p.price}" oninput="document.getElementById('p_manual').checked=true"><button class="btn s fx" onclick="document.getElementById('p_manual').checked=false;pfCalc(true)">Auto</button></div><label class="chk small" style="margin-top:4px"><input type="checkbox" id="p_manual" ${p.priceManual?"checked":""}> manual price (don't auto-update)</label></div><div class="field"><label class="f">Compare-at / MSRP</label><input type="number" step="0.01" id="p_msrp" value="${p.msrp||""}"></div></div>
  <div class="grid g3"><div class="field"><label class="f">MAP — vendor minimum advertised price</label><input type="number" step="0.01" id="p_map" value="${p.map||""}" placeholder="promotions & tags never go below this"></div><div class="field" style="grid-column:span 2"><label class="f">Matching pieces (shown as "goes with this" at the register)</label><div class="rel"><input type="text" id="rel_q" placeholder="Search a matching item…" oninput="relSearch(this.value)" autocomplete="off"><div id="rel_res"></div></div><div id="rel_lines" class="chips" style="margin-top:6px"></div></div></div>
  <div class="grid g4"><div class="field"><label class="f">In stock${feat("locations")&&locations().length?" (total)":""}</label><input type="number" id="p_stock" value="${p.stock}" ${p.isKit?"disabled":""}>${feat("locations")&&locations().length?`<select id="p_loc" style="margin-top:4px">${opts(locations(),defaultLoc("receive")?.id,x=>"changes go to "+x.name)}</select>`:""}</div><div class="field"><label class="f">Reorder at</label><input type="number" id="p_reorder" value="${p.reorderAt}"></div><div class="field"><label class="f">Pieces per unit</label><input type="number" id="p_pieces" value="${p.pieces||1}" ${p.isKit?"disabled":""}></div><div class="field"><label class="f">Warranty (years)</label><input type="number" id="p_warr" value="${p.warrantyYears||0}"></div></div>
  <div class="grid g2"><div class="chk"><input type="checkbox" id="p_floor" ${p.floorSample?"checked":""}><label for="p_floor">Floor sample (as-is)</label></div><div class="chk"><input type="checkbox" id="p_iskit" ${p.isKit?"checked":""} onchange="document.getElementById('kitbox').style.display=this.checked?'':'none';document.getElementById('p_stock').disabled=this.checked;pfCalc()"><label for="p_iskit">This is a kit made of other SKUs (e.g. King bed = headboard + footboard + rails)</label></div></div>
  <div id="kitbox" class="card" style="${p.isKit?"":"display:none"};padding:12px;margin-bottom:12px"><b class="small">Kit components</b><div class="field rel" style="margin-top:6px"><input type="text" id="kit_q" placeholder="Search a component SKU or name…" oninput="kitSearch(this.value)" autocomplete="off"><div id="kit_res"></div></div><div id="kit_lines"></div><div class="muted small" style="margin-top:6px">Kit stock = what you can build from components; selling the kit takes the components out of stock.</div></div>
  <div class="field"><label class="f">Notes</label><input type="text" id="p_notes" value="${esc(p.notes||"")}"></div>
  <div class="actions">${id&&isManager()?`<button class="btn d" onclick="confirmDo('Delete this item?',()=>{remove('products','${id}');closeModal();render()})">Delete</button>`:""}<button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="saveProduct('${id||""}')">Save item</button></div>`,true);
  window._kit=(p.kitItems||[]).map(k=>Object.assign({},k)); window._photo=p.photo||""; window._rel=(p.related||[]).slice(); kitRender(); relRender(); pfVendor();
}
function pfVendor(){ const vid=fv("p_vendor"); const v=byId("vendors",vid); const r=Object.assign({},costRules(),vendorRules(v)); const set=(id,t)=>{const e=document.getElementById(id); if(e) e.textContent=t;}; set("p_fr_lbl",`(blank = ${r.freightPct}% of cost)`); set("p_ad_lbl",`(blank = ${r.addPct}%)`); set("p_su_lbl",`(blank = ${money(r.surchargeFlat)}${r.surchargePct?" + "+r.surchargePct+"%":""})`); const cat=fv("p_cat"); const mult=(vendorRules(v).multiplier||categoryMultiplier(cat)||costRules().multiplier); set("p_mu_lbl",`(blank = ×${mult})`); set("p_rulesrc",v?`Using ${esc(v.name)}'s cost rules${Object.keys(vendorRules(v)).length?"":" (none set — store defaults apply)"}. Leave the fields blank to follow them; type a value to override for this item.`:"No vendor selected — store default cost rules apply."); pfCalc(); }
function pfCat(cat){ const sub=document.getElementById("p_sub"); sub.innerHTML=optsList(subcats(cat),"","—"); document.getElementById("matfields").style.display=cat==="Mattress"?"":"none"; pfVendor(); }
function pfReadCost(){ const v=id=>{const e=document.getElementById(id); return e&&e.value!==""?+e.value:undefined}; const isKit=fchk("p_iskit"); const tmp={cost:v("p_cost")||0,freight:v("p_freight"),addPct:v("p_addpct"),surcharge:v("p_sur"),multiplier:v("p_mult"),isKit,kitItems:window._kit||[],vendorId:fv("p_vendor"),category:fv("p_cat")}; return tmp; }
function pfCalc(force){ const tmp=pfReadCost(); const landed=landedCost(tmp); const el=document.getElementById("p_landed"); if(el) el.value=money(landed); const manual=fchk("p_manual"); if(force||!manual){ const pr=document.getElementById("p_price"); if(pr) pr.value=suggestPrice(tmp); } }
function kitSearch(q){ q=q.toLowerCase(); const r=document.getElementById("kit_res"); if(!q){r.innerHTML="";return} const hits=S.products.filter(p=>!p.isKit&&[p.sku,p.name,p.model,p.collection].join(" ").toLowerCase().includes(q)).slice(0,8); r.innerHTML=hits.length?`<div class="search-res">${hits.map(p=>`<div onmousedown="kitAdd('${p.id}')"><span><b>${esc(p.sku)}</b> ${esc(p.name)}</span><span class="muted">${money(landedCost(p))} landed · ${p.stock||0} in stock</span></div>`).join("")}</div>`:""; }
function kitAdd(pid){ const ex=window._kit.find(k=>k.productId===pid); if(ex) ex.qty++; else window._kit.push({productId:pid,qty:1}); document.getElementById("kit_q").value=""; document.getElementById("kit_res").innerHTML=""; kitRender(); pfCalc(); }
function kitRender(){ const el=document.getElementById("kit_lines"); if(!el) return; el.innerHTML=window._kit.map((k,i)=>{const c=byId("products",k.productId); return `<div class="row" style="padding:6px 0;border-bottom:1px solid var(--line2)"><span>${esc(c?.name||"?")} <span class="muted small">${esc(c?.sku||"")} · ${money(c?landedCost(c):0)} landed</span></span><input type="number" min="1" value="${k.qty}" style="max-width:70px" onchange="window._kit[${i}].qty=+this.value||1;kitRender();pfCalc()"><button class="btn s fx" onclick="window._kit.splice(${i},1);kitRender();pfCalc()">✕</button></div>`}).join("")||`<p class="muted small">No components yet.</p>`; }
function relSearch(q){ q=q.toLowerCase(); const r=document.getElementById("rel_res"); if(!q){r.innerHTML="";return} const hits=S.products.filter(p=>[p.sku,p.name,p.model,p.collection].join(" ").toLowerCase().includes(q)).slice(0,8); r.innerHTML=hits.length?`<div class="search-res">${hits.map(p=>`<div onmousedown="relAdd('${p.id}')"><span><b>${esc(p.sku)}</b> ${esc(p.name)}</span><span>${money(p.price)}</span></div>`).join("")}</div>`:""; }
function relAdd(pid){ if(!window._rel.includes(pid)) window._rel.push(pid); document.getElementById("rel_q").value=""; document.getElementById("rel_res").innerHTML=""; relRender(); }
function relRender(){ const el=document.getElementById("rel_lines"); if(!el) return; el.innerHTML=(window._rel||[]).map((id,i)=>{const p=byId("products",id); return p?`<span class="chip">${esc(p.name)} <a href="#" onclick="window._rel.splice(${i},1);relRender();return false" style="margin-left:4px">✕</a></span>`:""}).join("")||`<span class="muted small">None yet.</span>`; }
function uploadProductPhoto(input){ const f=input.files&&input.files[0]; if(!f) return; const img=new Image(); const url=URL.createObjectURL(f); img.onload=()=>{ const s=Math.min(1,280/Math.max(img.width,img.height)); const cv=document.createElement("canvas"); cv.width=img.width*s; cv.height=img.height*s; cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height); window._photo=cv.toDataURL("image/jpeg",0.7); URL.revokeObjectURL(url); const pv=document.getElementById("p_photo_prev"); if(pv) pv.innerHTML=`<img src="${window._photo}" style="width:40px;height:40px;object-fit:cover;border-radius:8px">`; input.value=""; }; img.src=url; }
async function saveProduct(id){
  const prev=byId("products",id)||{}; const v=x=>{const e=document.getElementById(x); return e&&e.value!==""?+e.value:""};
  const p=Object.assign({},prev,{id:id||undefined,sku:fv("p_sku").trim(),model:fv("p_model").trim(),collection:fv("p_coll").trim(),name:fv("p_name").trim(),category:fv("p_cat"),subcategory:fv("p_sub"),vendorId:fv("p_vendor"),color:fv("p_color").trim(),finish:fv("p_finish").trim(),size:fv("p_size").trim(),dims:fv("p_dims").trim(),vendorSku:fv("p_vsku").trim(),bin:fv("p_bin").trim(),cost:fnum("p_cost"),freight:v("p_freight"),addPct:v("p_addpct"),surcharge:v("p_sur"),multiplier:v("p_mult"),price:fnum("p_price"),priceManual:fchk("p_manual"),msrp:fnum("p_msrp"),map:fnum("p_map")||"",related:(window._rel||[]).filter(x=>byId("products",x)&&x!==id),reorderAt:fnum("p_reorder"),pieces:fnum("p_pieces")||1,warrantyYears:fnum("p_warr"),notes:fv("p_notes").trim(),floorSample:fchk("p_floor"),isKit:fchk("p_iskit"),kitItems:fchk("p_iskit")?(window._kit||[]).filter(k=>byId("products",k.productId)):[],photo:window._photo||""});
  if(p.category==="Mattress"){ Object.assign(p,{comfort:fv("p_comfort"),matType:fv("p_mtype"),trial:fv("p_trial")==="1"}); }
  if(!p.sku) p.sku=storeSettings().skuPrefix+"-"+(1000+S.products.length+1);
  if(!p.name) return toast("Name is required.",true);
  if(S.products.some(x=>x.sku===p.sku&&x.id!==p.id)) return toast("That SKU already exists.",true);
  if(p.isKit&&!p.kitItems.length) return toast("Add at least one component to the kit.",true);
  if(p.isKit&&p.kitItems.some(k=>k.productId===p.id)) return toast("A kit can't contain itself.",true);
  p.landed=landedCost(p); if(!p.priceManual) p.price=suggestPrice(p); if(p.map&&p.price<+p.map){ p.price=+p.map; toast("Price raised to the vendor MAP of "+money(p.map)); }
  if(p.floorSample&&!prev.floorSample) p.floorSampleSince=todayISO(); if(!p.floorSample) delete p.floorSampleSince;
  if(!p.createdAt) p.createdAt=todayISO();
  if(p.isKit){ p.stock=0; p.pieces=kitPieces(p)||1; } else { const total=fnum("p_stock"); if(feat("locations")&&locations().length){ p.stock=prev.stock||0; if(!prev.id) p.stockBy={}; setStockTotal(p,total,fv("p_loc")||undefined); } else p.stock=total; }
  await save("products",p); closeModal(); render(); toast("Item saved");
}
async function repriceVendor(vid){ const v=byId("vendors",vid); const items=S.products.filter(p=>p.vendorId===vid); if(!items.length) return toast("No items from this vendor.",true); if(!confirm(`Recalculate landed cost and price for ${items.length} ${v.name} item${items.length===1?"":"s"} (items marked manual keep their price)?`)) return; let n=0; for(const p of items){ p.landed=landedCost(p); if(!p.priceManual){ const np=suggestPrice(p); if(np!==p.price){ p.price=np; n++; } } await save("products",p); } render(); toast(`${v.name}: ${n} price${n===1?"":"s"} updated`); }
async function repriceAll(){ if(!confirm("Recalculate landed cost and selling price for every item that isn't marked manual?")) return; let n=0; for(const p of S.products){ p.landed=landedCost(p); if(!p.priceManual){ const np=suggestPrice(p); if(np!==p.price){ p.price=np; n++; } } await save("products",p); } render(); toast(`${n} prices updated`); }

/* ---------- kits tab ---------- */
function renderKits(){ const kits=S.products.filter(p=>p.isKit).sort((a,b)=>a.name.localeCompare(b.name)); return `<div class="toolbar"><span class="grow muted">A kit is one SKU built from other SKUs — a King bed from a headboard, footboard and rails. Sell the kit and the components come out of stock; kits can also go inside packages.</span><button class="btn p" onclick="newKit()">New kit</button></div><div class="card">${table(kits,[["",p=>photoThumb(p,40)],["Kit",p=>`<b>${esc(p.name)}</b><div class="muted small">${esc(p.sku)}${p.model?" · "+esc(p.model):""}${p.collection?" · "+esc(p.collection):""}</div>`],["Components",p=>(p.kitItems||[]).map(k=>{const c=byId("products",k.productId);return `${k.qty}× ${esc(c?.name||"?")} <span class="muted small">(${c?(c.stock||0):0} in stock)</span>`}).join("<br>")],["Can build",p=>`<b>${kitStock(p)}</b>`,"n"],...(seesCost()?[["Landed",p=>money(landedCost(p)),"n"]]:[]),["Price",p=>money(effectivePrice(p)),"n"],...(has("margin")?[["Margin",p=>pct(p.price?(p.price-landedCost(p))/p.price:0),"n"]]:[]),["",p=>`<div class="bgroup"><button class="btn s" onclick="editProduct('${p.id}')">Edit</button><button class="btn s" onclick="cur=cur||newInvoice();addLine('${p.id}');go('pos')">Sell</button></div>`]],"No kits yet. Create one and pick its components.")}</div>`; }
function newKit(){ editProduct(); setTimeout(()=>{ const c=document.getElementById("p_iskit"); if(c&&!c.checked){ c.checked=true; const kb=document.getElementById("kitbox"); if(kb) kb.style.display=""; const s=document.getElementById("p_stock"); if(s) s.disabled=true; try{ pfCalc(); }catch(e){} } const n=document.getElementById("p_name"); if(n){ n.placeholder="e.g. Alder king panel bed (kit)"; n.focus(); } },30); }
/* ---------- packages ---------- */
function packagePrice(pk){ return +pk.price||0; }
function packageList(pk){ return (pk.items||[]).reduce((a,it)=>{const p=byId("products",it.productId); return a+(p?effectivePrice(p)*it.qty:0)},0); }
function renderPackages(){ return `<div class="toolbar"><span class="grow muted">Pre-built bundles. Pick one at the register and it drops in as a package group — add or remove pieces from there.</span><button class="btn p" onclick="editPackage()">New package</button></div><div class="card">${table(S.packages.filter(x=>x.active!==false).concat(S.packages.filter(x=>x.active===false)),[["Package",pk=>`<div class="row" style="flex-wrap:nowrap">${photoThumb({photo:pk.photo,name:pk.name},40)}<div><b>${esc(pk.name)}</b><div class="muted small">${esc(pk.description||"")}</div></div></div>`],["Includes",pk=>(pk.items||[]).map(it=>`${it.qty}× ${esc(byId("products",it.productId)?.name||"?")}`).join(", ")],["List",pk=>money(packageList(pk)),"n"],["Package price",pk=>`<b>${money(packagePrice(pk))}</b>${packageList(pk)>packagePrice(pk)?`<div class="muted small">saves ${money(packageList(pk)-packagePrice(pk))}</div>`:""}`,"n"],...(has("margin")?[["Margin",pk=>{const c=(pk.items||[]).reduce((a,it)=>{const p=byId("products",it.productId);return a+(p?landedCost(p)*it.qty:0)},0);return pct(pk.price?(pk.price-c)/pk.price:0)},"n"]]:[]),["",pk=>`<div class="bgroup"><button class="btn s" onclick="editPackage('${pk.id}')">Edit</button>${pk.active===false?'<span class="tag">inactive</span>':""}</div>`]],"No packages yet.")}</div>`; }
function editPackage(id){ const pk=byId("packages",id)||{name:"",description:"",items:[],price:0,active:true,photo:""}; window._pk=(pk.items||[]).map(x=>Object.assign({},x)); modal(`<h2>${id?"Edit package":"New package"}</h2><div class="grid g2"><div class="field"><label class="f">Package name</label><input type="text" id="pk_name" value="${esc(pk.name)}" placeholder="e.g. Alder 5-piece king bedroom"></div><div class="field"><label class="f">Description (shows on the invoice)</label><input type="text" id="pk_desc" value="${esc(pk.description||"")}"></div></div><div class="field rel"><label class="f">Add pieces (items or kits)</label><input type="text" id="pk_q" placeholder="Search SKU, name, collection…" oninput="pkSearch(this.value)" autocomplete="off"><div id="pk_res"></div></div>${S.products.some(p=>p.isKit)?`<div class="chips" style="margin:-4px 0 10px"><span class="muted small">Kits:</span>${S.products.filter(p=>p.isKit).slice(0,8).map(p=>`<button class="chip" onclick="pkAdd('${p.id}')">${esc(p.name)}</button>`).join("")}</div>`:""}<div id="pk_lines"></div><div class="grid g3" style="margin-top:10px"><div class="field"><label class="f">List total</label><input type="text" id="pk_list" readonly style="background:var(--sage2)"></div><div class="field"><label class="f">Package price</label><input type="number" step="1" id="pk_price" value="${pk.price||""}"></div><div class="field"><label class="f">Quick set</label><div class="bgroup"><button class="btn s" onclick="pkPct(10)">−10%</button><button class="btn s" onclick="pkPct(15)">−15%</button><button class="btn s" onclick="pkPct(20)">−20%</button></div></div></div><div class="chk"><input type="checkbox" id="pk_active" ${pk.active!==false?"checked":""}><label for="pk_active">Active (offered at the register and in the catalog)</label></div><div class="actions">${id?`<button class="btn d" onclick="confirmDo('Delete package?',()=>{remove('packages','${id}');closeModal();render()})">Delete</button>`:""}<button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="savePackage('${id||""}')">Save package</button></div>`,true); pkRender(); }
function pkSearch(q){ q=q.toLowerCase(); const r=document.getElementById("pk_res"); if(!q){r.innerHTML="";return} const hits=S.products.filter(p=>[p.sku,p.name,p.collection,p.model].join(" ").toLowerCase().includes(q)).slice(0,8); r.innerHTML=hits.length?`<div class="search-res">${hits.map(p=>`<div onmousedown="pkAdd('${p.id}')"><span><b>${esc(p.sku)}</b> ${esc(p.name)}${p.isKit?' <span class="tag">kit</span>':""}</span><span>${money(p.price)}</span></div>`).join("")}</div>`:""; }
function pkAdd(pid){ const ex=window._pk.find(x=>x.productId===pid); if(ex) ex.qty++; else window._pk.push({productId:pid,qty:1}); document.getElementById("pk_q").value=""; document.getElementById("pk_res").innerHTML=""; pkRender(); }
function pkRender(){ const el=document.getElementById("pk_lines"); if(!el) return; el.innerHTML=window._pk.map((it,i)=>{const p=byId("products",it.productId); return `<div class="row" style="padding:6px 0;border-bottom:1px solid var(--line2)"><span>${esc(p?.name||"?")} <span class="muted small">${money(p?.price||0)}</span></span><input type="number" min="1" value="${it.qty}" style="max-width:70px" onchange="window._pk[${i}].qty=+this.value||1;pkRender()"><button class="btn s fx" onclick="window._pk.splice(${i},1);pkRender()">✕</button></div>`}).join("")||`<p class="muted small">No pieces yet.</p>`; const list=window._pk.reduce((a,it)=>{const p=byId("products",it.productId);return a+(p?p.price*it.qty:0)},0); const le=document.getElementById("pk_list"); if(le) le.value=money(list); const pe=document.getElementById("pk_price"); if(pe&&!pe.value&&list) pe.value=applyRounding(list*0.9); }
function pkPct(pc){ const list=window._pk.reduce((a,it)=>{const p=byId("products",it.productId);return a+(p?p.price*it.qty:0)},0); document.getElementById("pk_price").value=applyRounding(list*(1-pc/100)); }
async function savePackage(id){ const pk=Object.assign({},byId("packages",id)||{},{id:id||undefined,name:fv("pk_name").trim(),description:fv("pk_desc").trim(),items:(window._pk||[]).filter(x=>byId("products",x.productId)),price:fnum("pk_price"),active:fchk("pk_active")}); if(!pk.name) return toast("Name is required.",true); if(!pk.items.length) return toast("Add at least one piece.",true); if(!pk.price) return toast("Set the package price.",true); await save("packages",pk); closeModal(); render(); }
function pickPackage(){ const list=S.packages.filter(x=>x.active!==false); if(!list.length) return toast("No packages yet — build them under Stock → Packages.",true); modal(`<h2>Add a package</h2>${table(list,[["Package",pk=>`<b>${esc(pk.name)}</b><div class="muted small">${(pk.items||[]).map(it=>`${it.qty}× ${esc(byId("products",it.productId)?.name||"?")}`).join(", ")}</div>`],["List",pk=>money(packageList(pk)),"n"],["Package",pk=>`<b>${money(pk.price)}</b>`,"n"],["",pk=>`<button class="btn s p" onclick="closeModal();addPackageToSale('${pk.id}')">Add</button>`]],"")}<div class="actions"><button class="btn" onclick="closeModal()">Cancel</button></div>`,true); }
function addPackageToSale(id){ const pk=byId("packages",id); if(!pk) return; if(!cur) cur=newInvoice(); const g={id:uid(),name:pk.name,price:pk.price,packageId:pk.id}; cur.groups=cur.groups||[]; cur.groups.push(g); for(const it of pk.items){ const p=byId("products",it.productId); if(!p) continue; const l=makeLine(p,it.qty); l.groupId=g.id; cur.lines.push(l); } render(); toast(pk.name+" added — you can add or remove pieces"); }
function addToGroup(gid){ const ids=[...selLines].filter(i=>cur.lines[i]&&!cur.lines[i].groupId); if(!ids.length) return toast("Select ungrouped items first."); ids.forEach(i=>cur.lines[i].groupId=gid); selLines.clear(); render(); }

/* ---------- collection / model suggestions ---------- */
function prefixOf(s){ return String(s||"").split(/[-_ ]/)[0].toUpperCase(); }
function collectionSuggestions(){ if(!cur||!cur.lines.length) return []; const inCart=new Set(cur.lines.map(l=>l.productId)); cur.lines.forEach(l=>(l.kit||[]).forEach(k=>inCart.add(k.productId))); S.products.filter(p=>p.isKit&&(p.kitItems||[]).some(k=>inCart.has(k.productId))).forEach(p=>{ if((p.kitItems||[]).every(k=>inCart.has(k.productId))) inCart.add(p.id); }); const keys=new Set(); if(!S.products.some(p=>p.related&&p.related.length)&&!cur.lines.some(l=>byId("products",l.productId)?.collection||byId("products",l.productId)?.model)) return []; cur.lines.forEach(l=>{ const p=byId("products",l.productId); if(!p) return; if(p.collection) keys.add("c:"+p.collection.toLowerCase()); if(p.model&&prefixOf(p.model).length>=3) keys.add("m:"+prefixOf(p.model)); }); if(!keys.size) return []; const out=[]; const rel=new Set(); cur.lines.forEach(l=>{ const p=byId("products",l.productId); (p?.related||[]).forEach(id=>rel.add(id)); }); for(const id of rel){ const p=byId("products",id); if(p&&!inCart.has(p.id)) out.push(p); } for(const p of S.products){ if(inCart.has(p.id)||out.includes(p)||p.isKit&&kitStock(p)<=0) continue; const kc=p.collection?"c:"+p.collection.toLowerCase():null, km=p.model?"m:"+prefixOf(p.model):null; if((kc&&keys.has(kc))||(km&&keys.has(km))) out.push(p); } return out.slice(0,8); }

/* ---------- delivery price matrix ---------- */
function deliveryMatrix(){ return Object.assign({},DEFAULT_MATRIX,storeSettings().deliveryMatrix||{}); }
function deliveryOptions(){ const o=storeSettings().deliveryOptions; const list=o&&o.length?o:DEFAULT_DELIVERY_OPTIONS; return list.map((x,i)=>Object.assign({id:x.id||("opt"+i),setup:x.setup!==undefined?x.setup:i===0,default:x.default!==undefined?x.default:i===0,carrier:!!x.carrier},x)); }
function defaultDeliveryOption(){ const l=deliveryOptions(); return l.find(o=>o.default)||l[0]; }
function bandIndex(v,bands){ let i=0; while(i<bands.length&&v>=bands[i]) i++; return i; }
function deliveryQuote(customer,orderTotal){ const st=storeSettings(); const m=deliveryMatrix(); let mi=null; if(customer&&customer.lat&&st.lat) mi=haversine({lat:+st.lat,lng:+st.lng},{lat:+customer.lat,lng:+customer.lng})*1.3; const di=mi===null?0:bandIndex(mi,m.distBands); const oi=bandIndex(orderTotal||0,m.orderBands); const row=m.fees[oi]||m.fees[m.fees.length-1]||[st.deliveryFee]; const base=row[Math.min(di,row.length-1)]; const beyond=mi!==null&&di>=m.distBands.length&&m.beyondFee!==undefined&&m.beyondFee!==""; return {fee:beyond?+m.beyondFee:base,mi,distLabel:mi===null?"distance unknown":di<m.distBands.length?`within ${m.distBands[di]} mi`:`over ${m.distBands[m.distBands.length-1]} mi`,orderLabel:oi<m.orderBands.length?`order under ${money(m.orderBands[oi])}`:`order ${money(m.orderBands[m.orderBands.length-1])}+`,options:deliveryOptions().map(o=>({id:o.id,name:o.name,setup:o.setup,carrier:o.carrier,fee:Math.max(0,(beyond?+m.beyondFee:base)+(+o.add||0))}))}; }
function zoneFee(customer){ const q=deliveryQuote(customer,cur?invTotals(Object.assign({},cur,{deliveryFee:0})).sub:0); return {fee:q.fee,name:q.distLabel,mi:q.mi||0}; }
function renderDeliveryPricing(){ const m=deliveryMatrix(); const opts=deliveryOptions(); const st=storeSettings();
  return `<h3 style="margin:14px 0 6px">Delivery price by order size and distance</h3><p class="muted small">Rows are order-subtotal bands, columns are road miles from the store pin. The register picks the fee automatically; staff can still change it.</p>
  <div class="tblwrap"><table><thead><tr><th>Order subtotal</th>${m.distBands.map((b,i)=>`<th class="n">≤ <input type="number" id="dm_d_${i}" value="${b}" style="width:70px;display:inline-block;padding:3px 6px"> mi</th>`).join("")}<th class="n">beyond</th></tr></thead><tbody>${m.fees.map((row,r)=>`<tr><td>${r<m.orderBands.length?`< $<input type="number" id="dm_o_${r}" value="${m.orderBands[r]}" style="width:90px;display:inline-block;padding:3px 6px">`:`$${m.orderBands[m.orderBands.length-1]}+`}</td>${m.distBands.map((b,c)=>`<td class="n"><input type="number" step="1" id="dm_f_${r}_${c}" value="${row[c]??""}" style="width:80px;display:inline-block;padding:3px 6px"></td>`).join("")}<td class="n">${r===0?`<input type="number" id="dm_beyond" value="${m.beyondFee??""}" placeholder="quote" style="width:80px;display:inline-block;padding:3px 6px">`:'<span class="muted small">same</span>'}</td></tr>`).join("")}</tbody></table></div>
  <div class="bgroup" style="margin:8px 0"><button class="btn s" onclick="matrixResize('orderBands',1)">+ order band</button><button class="btn s" onclick="matrixResize('orderBands',-1)">− order band</button><button class="btn s" onclick="matrixResize('distBands',1)">+ distance band</button><button class="btn s" onclick="matrixResize('distBands',-1)">− distance band</button></div>
  <h3 style="margin:14px 0 6px">Delivery methods shown at the register</h3><p class="muted small">Keep it simple — most stores need two or three. The default is pre-selected on every delivery sale; “includes setup” tells the crew to set up and remove packaging; “carrier” means no truck or route (UPS / FedEx / freight with a tracking number).</p><div class="tblwrap"><table><thead><tr><th>Method</th><th class="n">± fee vs matrix</th><th>Includes setup</th><th>Carrier</th><th>Default</th><th></th></tr></thead><tbody>${opts.map((o,i)=>`<tr><td><input type="text" id="do_n_${i}" value="${esc(o.name)}"></td><td class="n"><input type="number" step="1" id="do_a_${i}" value="${o.add}" style="max-width:100px"></td><td><input type="checkbox" id="do_s_${i}" ${o.setup?"checked":""}></td><td><input type="checkbox" id="do_c_${i}" ${o.carrier?"checked":""}></td><td><input type="radio" name="do_def" id="do_d_${i}" ${o.default?"checked":""}></td><td><button class="btn s d" onclick="(async()=>{const st=storeSettings();st.deliveryOptions=deliveryOptions().filter((x,j)=>j!==${i});await save('settings',st);render()})()">✕</button></td></tr>`).join("")}</tbody></table></div><button class="btn s" style="margin-top:6px" onclick="(async()=>{const st=storeSettings();st.deliveryOptions=deliveryOptions().concat([{id:uid(),name:'New method',add:0,setup:false,default:false,carrier:false}]);await save('settings',st);render()})()">+ method</button><p class="muted small" style="margin-top:6px">Saved with the Save button above.</p>`; }
async function matrixResize(which,delta){ const st=storeSettings(); const m=deliveryMatrix(); if(which==="orderBands"){ if(delta>0){ m.orderBands.push((m.orderBands.slice(-1)[0]||0)+1000); m.fees.push(m.fees[m.fees.length-1].slice()); } else if(m.orderBands.length>1){ m.orderBands.pop(); m.fees.pop(); } } else { if(delta>0){ m.distBands.push((m.distBands.slice(-1)[0]||0)+10); m.fees.forEach(r=>r.push(r[r.length-1]+40)); } else if(m.distBands.length>1){ m.distBands.pop(); m.fees.forEach(r=>r.pop()); } } st.deliveryMatrix=m; await save("settings",st); render(); }
function readMatrixForm(){ const m=deliveryMatrix(); if(!document.getElementById("dm_d_0")) return null; m.distBands=m.distBands.map((b,i)=>fnum("dm_d_"+i)||b); m.orderBands=m.orderBands.map((b,i)=>fnum("dm_o_"+i)||b); m.fees=m.fees.map((row,r)=>row.map((f,c)=>{const e=document.getElementById(`dm_f_${r}_${c}`); return e&&e.value!==""?+e.value:f;})); const be=document.getElementById("dm_beyond"); m.beyondFee=be&&be.value!==""?+be.value:""; const opts=deliveryOptions().map((o,i)=>({id:o.id,name:fv("do_n_"+i)||o.name,add:fnum("do_a_"+i),setup:fchk("do_s_"+i),carrier:fchk("do_c_"+i),default:fchk("do_d_"+i)})); if(!opts.some(o=>o.default)&&opts.length) opts[0].default=true; return {m,opts}; }

/* ---------- catalog (browse, add to cart, start sale) ---------- */
let catQ="", catCat="", catSub="", catColl="", catView="grid", catType="all";
function renderCatalog(){
  const q=catQ.toLowerCase(); const colls=[...new Set(S.products.map(p=>p.collection).filter(Boolean))].sort();
  let items=S.products.filter(p=>(catType==="all"||(catType==="kits"?p.isKit:catType==="items"?!p.isKit:false))&&(!catCat||p.category===catCat)&&(!catSub||p.subcategory===catSub)&&(!catColl||p.collection===catColl)&&(!q||[p.sku,p.name,p.model,p.collection,p.color,p.finish,p.size,p.category,p.subcategory].join(" ").toLowerCase().includes(q)));
  const inCart=cur?cur.lines:[]; const cartQty=pid=>inCart.filter(l=>l.productId===pid).reduce((a,l)=>a+l.qty,0); const T=cur?invTotals(cur):null;
  const pks=(catType==="all"||catType==="packages")?S.packages.filter(x=>x.active!==false&&(!q||[x.name,x.description||"",(x.items||[]).map(it=>byId("products",it.productId)?.name||"").join(" ")].join(" ").toLowerCase().includes(q))):[];
  return `<div class="topbar"><h1>Catalog</h1><input type="search" id="q_catQ" placeholder="Search name, model, collection, color…" value="${esc(catQ)}" oninput="catQ=this.value;render()" style="max-width:300px"></div><div class="sub" style="margin-bottom:12px">${[["all","All"],["items","Items"],["kits","Kits ("+S.products.filter(p=>p.isKit).length+")"],["packages","Packages ("+S.packages.filter(x=>x.active!==false).length+")"]].map(([k,l])=>`<button class="${catType===k?"on":""}" onclick="catType='${k}';render()">${l}</button>`).join("")}</div><div class="toolbar" style="margin-top:-4px"><select style="max-width:170px" onchange="catCat=this.value;catSub='';render()">${optsList(categoryNames(),catCat,"All categories")}</select>${catCat?`<select style="max-width:170px" onchange="catSub=this.value;render()">${optsList(subcats(catCat),catSub,"All "+catCat.toLowerCase())}</select>`:""}<select style="max-width:160px" onchange="catColl=this.value;render()">${optsList(colls,catColl,"All collections")}</select>${tagSel.size?`<button class="btn" onclick="printCatalogTags()">Print ${tagSel.size} tag${tagSel.size===1?"":"s"}</button><button class="btn" onclick="labelsFromSelection()">Stock labels</button><button class="btn s" onclick="tagSel.clear();render()">Clear</button>`:""}</div>
  ${cur&&cur.lines.length?`<div class="cartbar"><div><b>${cur.lines.reduce((a,l)=>a+l.qty,0)} item${cur.lines.reduce((a,l)=>a+l.qty,0)===1?"":"s"} in the sale</b> · ${money(T.sub)}${cur.customerId?" · "+esc(custName(cur.customerId)):""}</div><div class="bgroup"><button class="btn s" onclick="cur=null;render()">Clear</button><button class="btn s p" onclick="go('pos')">Open sale →</button></div></div>`:""}
  ${pks.length&&(catType==="packages"||(!catCat&&!catColl))?`${catType==="packages"?"":'<h3 style="margin:4px 0 8px">Packages</h3>'}<div class="catgrid" style="margin-bottom:16px">${pks.map(pk=>`<div class="catcard"><div class="catimg">${pk.photo?`<img src="${pk.photo}">`:`<div class="catph">${esc(initials(pk.name))}</div>`}</div><div class="catbody"><b>${esc(pk.name)}</b><div class="muted small">${(pk.items||[]).map(it=>`${it.qty}× ${esc(byId("products",it.productId)?.name||"?")}`).join(", ")}</div><div style="margin-top:6px"><b>${money(pk.price)}</b> <span class="muted small" style="text-decoration:line-through">${money(packageList(pk))}</span> <span class="tag ok">saves ${money(packageList(pk)-pk.price)}</span></div><div class="bgroup" style="margin-top:8px"><button class="btn s" onclick="packageQuickView('${pk.id}')">Details</button><button class="btn s p" onclick="addPackageToSale('${pk.id}')">Add package</button></div></div></div>`).join("")}</div>${catType==="all"?'<h3 style="margin:4px 0 8px">Items</h3>':""}`:catType==="packages"?`<div class="card empty">No packages match. Build them under Inventory → Packages.</div>`:""}
  ${catType==="packages"?"":`<div class="catgrid">${items.map(p=>{const promo=promoFor(p); const stk=effStock(p); const inc=cartQty(p.id); return `<div class="catcard"><div class="catimg" onclick="itemQuickView('${p.id}')">${p.photo?`<img src="${p.photo}">`:`<div class="catph">${esc(initials(p.name))}</div>`}${promo?`<span class="tag warn" style="position:absolute;top:8px;left:8px">${esc(promo.tagLine||"SALE")}</span>`:""}${p.floorSample?'<span class="tag info" style="position:absolute;top:8px;right:8px">floor sample</span>':p.isKit?'<span class="tag" style="position:absolute;top:8px;right:8px">kit</span>':""}</div><div class="catbody"><div class="row" style="flex-wrap:nowrap"><b style="flex:1">${esc(p.name)}</b><label class="chk small fx" title="select for price tags"><input type="checkbox" ${tagSel.has(p.id)?"checked":""} onchange="this.checked?tagSel.add('${p.id}'):tagSel.delete('${p.id}');tagQty['${p.id}']=tagQty['${p.id}']||1;render()"> tag</label></div><div class="muted small">${[p.collection,p.model,p.color||p.finish,p.size].filter(Boolean).map(esc).join(" · ")}</div><div class="row" style="margin-top:6px"><span>${promo?`<span class="muted small" style="text-decoration:line-through">${money(p.price)}</span> `:""}<b>${money(effectivePrice(p))}</b><div class="muted small">${feat("locations")&&locations().length&&!p.isKit?`${deliverableStock(p)>0?deliverableStock(p)+" deliverable":"special order"}${floorStock(p)?" · "+floorStock(p)+" on the floor":""}`:(stk>0?stk+" in stock":"special order")}${p.dims?" · "+esc(p.dims):""}</div></span><button class="btn s ${inc?"":"p"} fx" onclick="catalogAdd('${p.id}')">${inc?"+1 ("+inc+")":"Add"}</button></div></div></div>`}).join("")||`<div class="card empty">${catType==="kits"?"No kits yet — create them under Inventory → Kits.":"Nothing matches."}</div>`}</div>`}`;
}
function packageQuickView(id){ const pk=byId("packages",id); if(!pk) return; modal(`<h2>${esc(pk.name)}</h2>${pk.description?`<p class="muted">${esc(pk.description)}</p>`:""}${table((pk.items||[]).map(it=>({it,p:byId("products",it.productId)})),[["",x=>x.p?photoThumb(x.p,36):""],["Piece",x=>`${esc(x.p?.name||"?")}${x.p?.isKit?' <span class="tag">kit</span>':""}<div class="muted small">${esc(x.p?.sku||"")}${x.p?.dims?" · "+esc(x.p.dims):""}</div>`],["Qty",x=>x.it.qty,"n"],["Each",x=>x.p?money(effectivePrice(x.p)):"","n"],["Stock",x=>x.p?(effStock(x.p)>0?effStock(x.p)+" in stock":"special order"):""]],"")}<div class="tot" style="margin-top:10px"><span>List total</span><span style="text-decoration:line-through">${money(packageList(pk))}</span></div><div class="tot"><span><b>Package price</b></span><b>${money(pk.price)}</b></div><div class="tot muted small"><span>Customer saves</span><span>${money(packageList(pk)-pk.price)}</span></div><div class="actions"><button class="btn" onclick="closeModal()">Close</button>${has("packages")?`<button class="btn" onclick="closeModal();editPackage('${pk.id}')">Edit package</button>`:""}<button class="btn p" onclick="closeModal();addPackageToSale('${pk.id}')">Add to sale</button></div>`,true); }
function catalogAdd(pid){ if(!cur) cur=newInvoice(); addLine(pid); }
function specSheetHTML(p){ const st=storeSettings(); const promo=promoFor(p); return `<div class="page"><div style="display:flex;justify-content:space-between"><div>${logoHTML(48)}<h1>${esc(st.name)}</h1><div>${esc(st.address)}${st.phone?" · "+esc(st.phone):""}</div></div><div style="text-align:right"><h2>${esc(p.name)}</h2><div>${esc(p.sku)}${p.model?" · Model "+esc(p.model):""}</div></div></div>${p.photo?`<img src="${p.photo}" style="max-width:60%;max-height:320px;border-radius:12px;margin:16px 0">`:""}<table class="ptable">${[["Collection",p.collection],["Category",[p.category,p.subcategory].filter(Boolean).join(" › ")],["Color / finish",[p.color,p.finish].filter(Boolean).join(" · ")],["Size",p.size],["Dimensions",p.dims],["Comfort",isMattress(p)?[p.comfort,p.matType,p.height?p.height+'" profile':""].filter(Boolean).join(" · "):""],["Warranty",p.warrantyYears?p.warrantyYears+" years":""],["Sleep trial",isMattress(p)&&p.trial!==false?st.trialNights+" nights":""],["Kit includes",p.isKit?(p.kitItems||[]).map(k=>k.qty+"× "+(byId("products",k.productId)?.name||"")).join(", "):""]].filter(r=>r[1]).map(r=>`<tr><th style="width:160px">${esc(r[0])}</th><td>${esc(r[1])}</td></tr>`).join("")}</table><p style="font-size:26px;font-weight:800;margin:18px 0 4px">${money(effectivePrice(p))}${promo?` <span style="font-size:14px;font-weight:600">${esc(promo.tagLine||"SALE")} · was ${money(p.price)}</span>`:""}</p>${p.msrp?`<p>Compare at ${money(p.msrp)}</p>`:""}${p.notes?`<p style="margin-top:10px">${esc(p.notes)}</p>`:""}<p style="font-size:11px;margin-top:20px">Prepared ${dateFmt(todayISO())}. Prices subject to change; special orders may take ${byId("vendors",p.vendorId)?.leadDays||21} days.</p></div>`; }
function printSpecSheet(pid){ const p=byId("products",pid); if(p) printHTML(specSheetHTML(p)); }
function specSheetText(p){ const st=storeSettings(); return `${p.name}\n${[p.sku,p.model?"Model "+p.model:"",p.collection,p.color,p.finish,p.size,p.dims].filter(Boolean).join(" · ")}\n${isMattress(p)?[p.comfort,p.matType].filter(Boolean).join(" · ")+"\n":""}Price: ${money(effectivePrice(p))}${p.msrp?" (compare at "+money(p.msrp)+")":""}${p.warrantyYears?"\nWarranty: "+p.warrantyYears+" years":""}\n\n${st.name}${st.phone?" · "+st.phone:""}`; }
function printCatalogTags(){ if(!tagSel.size) return toast("Tick items on the cards first.",true); tagStyle=[...tagSel].every(id=>isMattress(byId("products",id)))?"mattress":"shelf"; printTags(); }
function itemQuickView(pid){ const p=byId("products",pid); const promo=promoFor(p); modal(`<h2>${esc(p.name)}</h2><div class="grid g2"><div>${p.photo?`<img src="${p.photo}" style="width:100%;border-radius:12px">`:`<div class="catph" style="height:220px;border-radius:12px">${esc(initials(p.name))}</div>`}</div><div><div class="tot"><span>Price</span><b>${money(effectivePrice(p))}${promo?` <span class="muted small" style="text-decoration:line-through">${money(p.price)}</span> <span class="tag warn">${esc(promo.name)}</span>`:""}</b></div>${p.msrp?`<div class="tot muted"><span>Compare at</span><span>${money(p.msrp)}</span></div>`:""}<div class="tot"><span>SKU · Model</span><span>${esc(p.sku)}${p.model?" · "+esc(p.model):""}</span></div>${p.collection?`<div class="tot"><span>Collection</span><span>${esc(p.collection)}</span></div>`:""}${p.color||p.finish?`<div class="tot"><span>Color / finish</span><span>${esc([p.color,p.finish].filter(Boolean).join(" · "))}</span></div>`:""}${p.size||p.dims?`<div class="tot"><span>Size</span><span>${esc([p.size,p.dims].filter(Boolean).join(" · "))}</span></div>`:""}${isMattress(p)?`<div class="tot"><span>Comfort</span><span>${esc(p.comfort||"")} · ${esc(p.matType||"")}</span></div>`:""}<div class="tot"><span>Availability</span><span>${feat("locations")&&locations().length&&!p.isKit?`${deliverableStock(p)>0?deliverableStock(p)+" deliverable":"special order · "+(byId("vendors",p.vendorId)?.leadDays||21)+" days"}${typeof vendorStockButton==="function"&&vendorStockButton(p)?" · "+vendorStockButton(p):""}${floorStock(p)?" · "+floorStock(p)+" on the floor":""}`:(effStock(p)>0?effStock(p)+" in stock":"special order · "+(byId("vendors",p.vendorId)?.leadDays||21)+" days")}</span></div>${p.isKit?`<div class="tot"><span>Kit of</span><span>${(p.kitItems||[]).map(k=>k.qty+"× "+esc(byId("products",k.productId)?.name||"?")).join(", ")}</span></div>`:""}${p.warrantyYears?`<div class="tot"><span>Warranty</span><span>${p.warrantyYears} yr</span></div>`:""}${p.notes?`<p class="muted small" style="margin-top:8px">${esc(p.notes)}</p>`:""}${seesCost()?`<div class="tot muted small"><span>Landed cost</span><span>${money(landedCost(p))} · margin ${pct(effectivePrice(p)?(effectivePrice(p)-landedCost(p))/effectivePrice(p):0)}</span></div>`:has("margin")?`<div class="tot muted small"><span>Margin</span><span>${pct(effectivePrice(p)?(effectivePrice(p)-landedCost(p))/effectivePrice(p):0)}</span></div>`:""}</div></div><div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn" onclick="printSpecSheet('${p.id}')">Print spec sheet</button><a class="btn" href="mailto:?subject=${encodeURIComponent(p.name+" — "+storeSettings().name)}&body=${encodeURIComponent(specSheetText(p))}">Email spec</a><button class="btn" onclick="tagSel.add('${p.id}');tagQty['${p.id}']=1;closeModal();printCatalogTags()">Print tag</button>${seesCost()?`<button class="btn" onclick="closeModal();editProduct('${p.id}')">Edit item</button>`:""}<button class="btn p" onclick="closeModal();catalogAdd('${p.id}')">Add to sale</button></div>`,true); }

/* ---------- category & cost-rule settings ---------- */
let pricingVendor="";
function merchPricingPartHTML(){ const r=costRules(); const v=pricingVendor?byId("vendors",pricingVendor):null; const ph=k=>v?`store default ${k==="surchargeFlat"?money(r[k]):k==="multiplier"?"×"+r[k]:r[k]+"%"}`:""; const vrl=v?vendorRules(v):{}; const val=k=>v?(vrl[k]!==undefined?vrl[k]:""):r[k]; const sample={cost:400,vendorId:v?v.id:""}; return `<h3 style="margin:0 0 6px">Landed cost & automatic pricing</h3><p class="muted small">Every supplier carries its own freight, extra costs, surcharge and markup. Choose a supplier to set its rules; "Store default" only covers items that have no supplier.</p>
  <div class="field"><label class="f">Rules for</label><select id="pr_scope" onchange="pricingVendor=this.value;render()" style="max-width:360px"><option value="" ${!pricingVendor?"selected":""}>Store default (items with no supplier)</option>${S.vendors.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<option value="${x.id}" ${pricingVendor===x.id?"selected":""}>${esc(x.name)} · ${S.products.filter(p=>p.vendorId===x.id).length} items</option>`).join("")}</select></div>
  ${v?`<p class="muted small">Blank fields inherit the store default. Items from ${esc(v.name)} follow these unless the item overrides them.</p>`:""}
  <div class="grid g4"><div class="field"><label class="f">Freight % of cost</label><input type="number" step="0.1" id="cr_freight" value="${val("freightPct")}" placeholder="${ph("freightPct")}"></div><div class="field"><label class="f">Extra cost %</label><input type="number" step="0.1" id="cr_add" value="${val("addPct")}" placeholder="${ph("addPct")}"></div><div class="field"><label class="f">Surcharge $ per item</label><input type="number" step="0.01" id="cr_surf" value="${val("surchargeFlat")}" placeholder="${ph("surchargeFlat")}"></div><div class="field"><label class="f">Surcharge %</label><input type="number" step="0.1" id="cr_surp" value="${val("surchargePct")}" placeholder="${ph("surchargePct")}"></div></div>
  <div class="grid g3"><div class="field"><label class="f">Price multiplier</label><input type="number" step="0.05" id="cr_mult" value="${v?(vrl.multiplier!==undefined?vrl.multiplier:""):r.multiplier}" placeholder="${ph("multiplier")}"></div><div class="field"><label class="f">Rounding</label><select id="cr_round">${v?`<option value="" ${!v.rounding?"selected":""}>Store default (${r.rounding})</option>`:""}${[["up","Round up"],["down","Round down"],["nearest","Nearest"]].map(([k,l])=>`<option value="${k}" ${(v?v.rounding:r.rounding)===k?"selected":""}>${l}</option>`).join("")}</select></div><div class="field"><label class="f">Cents</label><select id="cr_cents">${v?`<option value="" ${!v.cents?"selected":""}>Store default (${r.cents==="none"?"whole dollars":r.cents})</option>`:""}${[["none","Whole dollars (no cents)"],[".99","End in .99"],[".95","End in .95"],["keep","Keep exact cents"]].map(([k,l])=>`<option value="${k}" ${(v?v.cents:r.cents)===k?"selected":""}>${l}</option>`).join("")}</select></div></div>
  <p class="muted small">Example for ${v?esc(v.name):"the store default"}: cost $400 → landed ${money(landedCost(sample))} → price ${money(suggestPrice(sample))}.</p>
  <div class="row"><button class="btn p fx" onclick="saveMerchSettings()">Save ${v?esc(v.name)+"'s rules":"store default"}</button><button class="btn fx" onclick="saveMerchSettings().then(()=>${v?`repriceVendor('${v.id}')`:"repriceAll()"})">Save & re-price ${v?"this supplier's":"all"} items</button>${v?`<button class="btn fx" onclick="clearVendorRules('${v.id}')">Clear (use store default)</button>`:""}</div>
  <details style="margin:12px 0 4px"><summary class="btn s" style="display:inline-block">Multiplier by category ▾</summary><div class="grid g4" style="margin-top:10px">${categoryNames().map(c=>`<div class="field"><label class="f">${esc(c)}</label><input type="number" step="0.05" id="cm_${esc(c).replace(/[^A-Za-z0-9]/g,"_")}" value="${categoryMultiplier(c)||""}" placeholder="× ${r.multiplier}"></div>`).join("")}</div><p class="muted small">Used when neither the item nor its supplier sets a multiplier. Vendor MAP on an item is always the floor.</p></details>
  <h3 style="margin:16px 0 6px">All suppliers at a glance</h3><div class="tblwrap"><table><thead><tr><th>Supplier</th><th class="n">Items</th><th class="n">Freight</th><th class="n">Extra</th><th class="n">Surcharge</th><th class="n">Multiplier</th><th>Rounding</th><th class="n">$400 cost →</th><th></th></tr></thead><tbody>${[{id:"",name:"Store default"}].concat(S.vendors.slice().sort((a,b)=>a.name.localeCompare(b.name))).map(x=>{const rr=x.id?Object.assign({},r,vendorRules(byId("vendors",x.id))):r; const own=x.id?vendorRules(byId("vendors",x.id)):{}; const f=(k,fmt)=>`<span class="${own[k]!==undefined||!x.id?"":"muted"}">${fmt(rr[k])}</span>`; return `<tr><td><b>${esc(x.name)}</b></td><td class="n">${x.id?S.products.filter(p=>p.vendorId===x.id).length:S.products.filter(p=>!p.vendorId).length}</td><td class="n">${f("freightPct",v=>v+"%")}</td><td class="n">${f("addPct",v=>v+"%")}</td><td class="n">${f("surchargeFlat",v=>money(v))}${rr.surchargePct?` + ${rr.surchargePct}%`:""}</td><td class="n">${f("multiplier",v=>"×"+v)}</td><td>${rr.rounding} · ${rr.cents==="none"?"whole $":rr.cents}</td><td class="n">${money(suggestPrice({cost:400,vendorId:x.id}))}</td><td><button class="btn s" onclick="pricingVendor='${x.id}';render()">Edit</button></td></tr>`}).join("")}</tbody></table></div><p class="muted small" style="margin-top:6px">Grey values are inherited from the store default.</p>
  `; }
function renderMerchSettings(){ const r=costRules(); const v=pricingVendor?byId("vendors",pricingVendor):null; const ph=k=>v?`store default ${k==="surchargeFlat"?money(r[k]):k==="multiplier"?"×"+r[k]:r[k]+"%"}`:""; const vrl=v?vendorRules(v):{}; const val=k=>v?(vrl[k]!==undefined?vrl[k]:""):r[k];
  const sample={cost:400,vendorId:v?v.id:""};
  return `<div class="card" style="max-width:860px">${window._merchPart==="inventory"?"":merchPricingPartHTML()}${window._merchPart==="pricing"?"":`<h3 style="margin:18px 0 8px">Colors & finishes</h3><p class="muted small">Standard names so items are entered consistently — they appear as suggestions on the item form (anything typed on an item is suggested too).</p><label class="f">Colors</label>${chipList("colors",colorNames(),{placeholder:"Add a color…"})}<label class="f" style="margin-top:8px;display:block">Covers / finishes</label>${chipList("finishes",finishNames(),{placeholder:"Add a finish…"})}
  <h3 style="margin:18px 0 8px">Categories & sub-categories</h3><p class="muted small">Add, rename, reorder or remove. Renaming updates the items that use it; removing a category asks where to move its items.</p>${renderCategoryEditor()}</div>`}`; }
function renderCategoryEditor(){ const cats=categories(); return `<div id="cat_editor">${cats.map((c,i)=>`<div class="catrow"><div class="head"><input type="text" value="${esc(c.name)}" onchange="catRename(${i},this.value)" title="Category name"><span class="muted small">${S.products.filter(p=>p.category===c.name).length} items</span><span style="flex:1"></span><button class="btn s" onclick="catMove(${i},-1)" ${i===0?"disabled":""} title="Move up">↑</button><button class="btn s" onclick="catMove(${i},1)" ${i===cats.length-1?"disabled":""} title="Move down">↓</button><button class="btn s d" onclick="catRemove(${i})">Remove</button></div><div class="subs">${c.subs.map((s,j)=>`<span class="chip" title="Click the name to rename"><span onclick="subRename(${i},${j})" style="cursor:text">${esc(s)}</span><a href="#" onclick="subRemove(${i},${j});return false" title="Remove">✕</a></span>`).join("")}<input type="text" placeholder="Add sub-category…" onkeydown="if(event.key==='Enter'){event.preventDefault();subAdd(${i},this.value);this.value='';}"><button class="btn s" onclick="subAdd(${i},this.previousElementSibling.value);this.previousElementSibling.value=''">Add</button></div></div>`).join("")}<div class="row" style="margin-top:8px"><input type="text" id="cat_new" placeholder="New category name…" style="max-width:260px" onkeydown="if(event.key==='Enter'){event.preventDefault();catAdd()}"><button class="btn fx" onclick="catAdd()">Add category</button><span class="fx"><button class="btn s" onclick="confirmDo('Reset the category list to the defaults? Items keep their current categories.',()=>catReset())">Reset to defaults</button></span></div></div>`; }
async function saveCats(cats){ const st=storeSettings(); st.categories=cats; await save("settings",st); render(); }
async function catAdd(){ const name=(fv("cat_new")||"").trim(); if(!name) return toast("Type a category name.",true); const cats=categories(); if(cats.some(c=>c.name.toLowerCase()===name.toLowerCase())) return toast("That category already exists.",true); cats.push({name,subs:[]}); await saveCats(cats); }
async function catRename(i,name){ name=(name||"").trim(); const cats=categories(); if(!name||name===cats[i].name){ render(); return; } if(cats.some((c,j)=>j!==i&&c.name.toLowerCase()===name.toLowerCase())){ toast("That name is already used.",true); render(); return; } const old=cats[i].name; cats[i].name=name; for(const p of S.products){ if(p.category===old){ p.category=name; await save("products",p); } } for(const x of S.promotions||[]){ if(x.category===old){ x.category=name; await save("promotions",x); } } const st=storeSettings(); if(st.categoryRules&&st.categoryRules[old]){ st.categoryRules[name]=st.categoryRules[old]; delete st.categoryRules[old]; } await saveCats(cats); toast(`Renamed to ${name}`); }
async function catMove(i,d){ const cats=categories(); const j=i+d; if(j<0||j>=cats.length) return; [cats[i],cats[j]]=[cats[j],cats[i]]; await saveCats(cats); }
function catRemove(i){ const cats=categories(); const c=cats[i]; const n=S.products.filter(p=>p.category===c.name).length; const others=cats.filter((x,j)=>j!==i); if(!others.length) return toast("Keep at least one category.",true); modal(`<h2>Remove ${esc(c.name)}</h2><p class="muted">${n?`${n} item${n===1?"":"s"} use this category. Choose where they go.`:"No items use this category."}</p>${n?`<div class="field"><label class="f">Move items to</label><select id="cr_to">${optsList(others.map(x=>x.name),others[0].name)}</select></div>`:""}<div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn d" onclick="doCatRemove(${i})">Remove category</button></div>`); }
async function doCatRemove(i){ const cats=categories(); const c=cats[i]; const to=fv("cr_to"); for(const p of S.products){ if(p.category===c.name){ p.category=to||""; p.subcategory=""; await save("products",p); } } cats.splice(i,1); closeModal(); await saveCats(cats); }
async function subAdd(i,name){ name=(name||"").trim(); if(!name) return; const cats=categories(); if(cats[i].subs.some(s=>s.toLowerCase()===name.toLowerCase())) return toast("Already in the list.",true); cats[i].subs.push(name); await saveCats(cats); }
async function subRemove(i,j){ const cats=categories(); const s=cats[i].subs[j]; const n=S.products.filter(p=>p.category===cats[i].name&&p.subcategory===s).length; if(n&&!confirm(`${n} item${n===1?"":"s"} use "${s}". Remove it anyway? (they keep the category, sub-category is cleared)`)) return; for(const p of S.products){ if(p.category===cats[i].name&&p.subcategory===s){ p.subcategory=""; await save("products",p); } } cats[i].subs.splice(j,1); await saveCats(cats); }
async function subRename(i,j){ const cats=categories(); const old=cats[i].subs[j]; const name=(prompt("Rename sub-category",old)||"").trim(); if(!name||name===old) return; cats[i].subs[j]=name; for(const p of S.products){ if(p.category===cats[i].name&&p.subcategory===old){ p.subcategory=name; await save("products",p); } } await saveCats(cats); }
async function catReset(){ await saveCats(DEFAULT_CATEGORIES.map(([name,subs])=>({name,subs:subs.slice()}))); }
async function saveMerchSettings(){ const st=storeSettings(); const cr={}; for(const c of categoryNames()){ const v=fnum("cm_"+c.replace(/[^A-Za-z0-9]/g,"_")); if(v) cr[c]={multiplier:v}; } st.categoryRules=cr; const nv=x=>fv(x)===""?"":fnum(x);
  if(pricingVendor){ const v=byId("vendors",pricingVendor); if(v){ Object.assign(v,{freightPct:nv("cr_freight"),addPct:nv("cr_add"),surchargeFlat:nv("cr_surf"),surchargePct:nv("cr_surp"),multiplier:nv("cr_mult"),rounding:fv("cr_round")||"",cents:fv("cr_cents")||""}); delete v.markup; await save("vendors",v); } await save("settings",st); render(); toast((v?v.name:"Supplier")+" rules saved"); return; }
  st.costRules={freightPct:fnum("cr_freight"),addPct:fnum("cr_add"),surchargeFlat:fnum("cr_surf"),surchargePct:fnum("cr_surp"),multiplier:fnum("cr_mult")||2,rounding:fv("cr_round")||"up",cents:fv("cr_cents")||"none"}; await save("settings",st); render(); toast("Store default rules saved"); }
async function clearVendorRules(vid){ const v=byId("vendors",vid); if(!v) return; ["freightPct","addPct","surchargeFlat","surchargePct","multiplier","rounding","cents"].forEach(k=>v[k]=""); delete v.markup; await save("vendors",v); render(); toast(v.name+" now follows the store default"); }
